new = '''# --------------------------------------------------------------------------- #
#  Policy
# --------------------------------------------------------------------------- #

class Context(object):
    """Directory, account and gateway authority derived from the batch header."""

    def __init__(self, batch):
        self.alias = {}
        directory = batch.get("directory")
        if isinstance(directory, dict):
            for canon, aliases in directory.items():
                if not isinstance(canon, str):
                    continue
                self.alias[canon] = canon          # canonical is always an alias
                if isinstance(aliases, (list, tuple)):
                    for a in aliases:
                        if isinstance(a, str):
                            self.alias[a] = canon
        accounts = batch.get("accounts")
        self.accounts = accounts if isinstance(accounts, dict) else {}
        gateways = batch.get("gateways")
        self.gateways = gateways if isinstance(gateways, dict) else {}
        self._pool = {}
        self._domains = {}
        self._authority = {}

    def allowed_pool(self, subject):
        """(primary, frozenset of allowed identities) or None for unknown subject."""
        if subject in self._pool:
            return self._pool[subject]
        acc = self.accounts.get(subject)
        result = None
        if isinstance(acc, dict) and isinstance(acc.get("primary"), str):
            pool = set((acc["primary"],))
            allow = acc.get("allow")
            if isinstance(allow, (list, tuple)):
                for a in allow:
                    if isinstance(a, str):
                        pool.add(a)                # primary is implicitly allowed
            result = (acc["primary"], frozenset(pool))
        self._pool[subject] = result
        return result

    def local_domains(self, gw_name):
        if gw_name in self._domains:
            return self._domains[gw_name]
        gw = self.gateways.get(gw_name)
        result = None
        if isinstance(gw, dict):
            domains = gw.get("local_domains")
            if isinstance(domains, (list, tuple)):
                result = frozenset(d for d in domains if isinstance(d, str))
        self._domains[gw_name] = result
        return result

    def peer_authority(self, gw_name, peer_name):
        """(known_peer, frozenset of domains) or (False, None) when unlisted."""
        key = (gw_name, peer_name)
        if key in self._authority:
            return self._authority[key]
        gw = self.gateways.get(gw_name)
        result = (False, None)
        if isinstance(gw, dict):
            peers = gw.get("peers")
            if isinstance(peers, dict) and peers.get(peer_name) is not None:
                domains = peers[peer_name]
                allowed = (frozenset(d for d in domains if isinstance(d, str))
                           if isinstance(domains, (list, tuple)) else frozenset())
                result = (True, allowed)
        self._authority[key] = result
        return result


def resolve(claim, ctx):
    ident = ctx.alias.get(claim)
    if ident is None:
        denied()                                   # no directory identity for claim
    return ident


def select_local(req, subject, gw_name, ctx):
    account = ctx.allowed_pool(subject)
    if account is None:
        raise Reject("unauthenticated")             # unknown local subject
    primary, pool = account
    hosted = ctx.local_domains(gw_name)
    if hosted is None:
        denied()

    def authorized(claim):
        ident = resolve(claim, ctx)
        if ident not in pool or domain_of(ident) not in hosted:
            denied()
        return ident

    selected = None
    if req["ppi"] is not None:
        selected = authorized(req["ppi"])
    if req["from_uri"] != ANONYMOUS:
        ident = authorized(req["from_uri"])
        if selected is None:
            selected = ident
    if selected is None:
        selected = authorized(primary)              # primary must be allowed/hosted too
    return selected, "local"


def select_peer(req, peer_name, gw_name, ctx):
    known, authority = ctx.peer_authority(gw_name, peer_name)
    if not known:
        raise Reject("unauthenticated")             # unknown peer
    if not req["has_pai"]:
        raise Reject("unauthenticated")             # listed peer without PAI
    selected = None
    for claim in req["pai"]:
        ident = resolve(claim, ctx)
        if selected is None:
            selected = ident
        elif ident != selected:
            denied()                                # asserted identities disagree
    if domain_of(selected) not in authority:
        denied()                                    # peer not authoritative here
    for claim in (req["from_uri"], req["ppi"], req["rpid"]):
        if claim is None or claim == ANONYMOUS:
            continue                                # anonymous From is permitted
        if resolve(claim, ctx) != selected:
            denied()
    return selected, "peer"


def build_wire(req, selected, private, trusted_out):
    lines = [req["method"] + " " + req["ruri"] + " SIP/2.0"]
    line = "From: <" + (ANONYMOUS if private else selected) + ">"
    if req["from_tag"] is not None:
        line += ";tag=" + req["from_tag"]
    lines.append(line)
    line = "To: <" + req["to_uri"] + ">"
    if req["to_tag"] is not None:
        line += ";tag=" + req["to_tag"]
    lines.append(line)
    lines.append("Call-ID: " + req["call_id"])
    lines.append("CSeq: " + str(req["cseq"]) + " " + req["method"])
    lines.append("Privacy: " + ("id" if private else "none"))
    if (not private) or trusted_out:
        lines.append("P-Asserted-Identity: <" + selected + ">")
    if req["content_type"] is not None:
        lines.append("Content-Type: " + req["content_type"])
    lines.append("Content-Length: " + str(len(req["body"])))
    return "\\r\\n".join(lines) + "\\r\\n\\r\\n" + req["body"]


def forwarded(job, index, results):
    if "raw" in job:
        text = job.get("raw")
        if not isinstance(text, str):
            bad()
        return text
    if "source" in job:
        src = job.get("source")
        if (not isinstance(src, int) or isinstance(src, bool) or src < 0
                or src >= index or src >= len(results)):
            raise Reject("upstream")
        previous = results[src]
        if previous.get("status") != "accept":
            raise Reject("upstream")
        text = previous.get("wire")
        if not isinstance(text, str):
            raise Reject("upstream")
        return text
    bad()                                          # no request text supplied


def handle(job, index, results, ctx):
    if not isinstance(job, dict):
        bad()
    text = forwarded(job, index, results)
    req = parse_request(text)                      # grammar first, always
    gw_name = job.get("gateway")
    ingress = job.get("ingress")
    kind = ingress.get("kind") if isinstance(ingress, dict) else None
    private = req["from_uri"] == ANONYMOUS or req["privacy_id"]
    if kind == "local":
        selected, basis = select_local(req, ingress.get("subject"), gw_name, ctx)
    elif kind == "peer":
        selected, basis = select_peer(req, ingress.get("name"), gw_name, ctx)
    else:
        raise Reject("unauthenticated")             # no evidence at all
    wire = build_wire(req, selected, private, bool(job.get("trusted_out")))
    return {"status": "accept", "identity": selected, "basis": basis,
            "private": bool(private), "wire": wire}


'''
